(() => {
  const CHART_HEIGHT = 640;
  const MIN_CHART_WIDTH = 520;
  const FORCE_TICKS = 320;
  const TOOLTIP_PAD = 12;

  const tooltip = d3.select('#tooltip');
  const priceCache = new Map();
  let selectedTicker = null;

  function escapeHtml(value) {
    return String(value ?? '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function formatMarketCap(value) {
    if (value == null || !Number.isFinite(+value)) return '—';
    const v = +value;
    const abs = Math.abs(v);

    const trim = (num) => {
      const decimals = num >= 10 ? 1 : 2;
      return num
        .toFixed(decimals)
        .replace(/\.0+$/, '')
        .replace(/(\.\d*[1-9])0+$/, '$1');
    };

    if (abs >= 1e12) return `${trim(v / 1e12)}T`;
    if (abs >= 1e9) return `${trim(v / 1e9)}B`;
    if (abs >= 1e6) return `${trim(v / 1e6)}M`;
    if (abs >= 1e3) return `${trim(v / 1e3)}K`;
    return `${Math.round(v)}`;
  }

  function downsampleEvenly(arr, n) {
    if (!Array.isArray(arr) || arr.length <= n) return arr || [];
    if (n <= 0) return [];
    const out = [];
    const last = arr.length - 1;
    for (let i = 0; i < n; i += 1) {
      const idx = Math.round((i * last) / (n - 1));
      out.push(arr[idx]);
    }
    return out;
  }

  function normalizeStockRow(d) {
    const sectorRaw = (d.sector ?? '').toString().trim();
    const sector = sectorRaw && sectorRaw.toLowerCase() !== 'nan' ? sectorRaw : 'Unknown';

    const marketCapRaw = d.marketCap;
    const marketCapNum = marketCapRaw == null || marketCapRaw === '' ? NaN : +marketCapRaw;
    const marketCap = Number.isFinite(marketCapNum) ? marketCapNum : null;

    const fullName = (d['full name'] ?? d.fullName ?? '').toString().trim();
    const country = (d.country ?? '').toString().trim() || null;
    const website = (d.website ?? '').toString().trim() || null;

    return {
      ticker: (d.ticker ?? '').toString().trim(),
      sector,
      fullName,
      marketCap,
      country,
      website,
      isETF: sector === 'ETF' || marketCap == null,
    };
  }

  async function loadStocks() {
    try {
      const rows = await d3.csv('data/stock-descriptions.csv');
      if (!rows || !rows.length) throw new Error('Empty CSV');
      return rows.map(normalizeStockRow);
    } catch (err) {
      return EMBEDDED_STOCKS.map(normalizeStockRow);
    }
  }

  async function loadPriceSeries(ticker) {
    if (priceCache.has(ticker)) return priceCache.get(ticker);

    let series = null;
    try {
      const rows = await d3.csv(`data/indiv-stock/${ticker}.csv`);
      series = rows
        .map(r => {
          const date = (r.Date ?? '').toString().trim();
          const close = +(r['Adjusted Close'] ?? r.Close);
          return { date, close };
        })
        .filter(p => p.date && Number.isFinite(p.close));
    } catch (err) {
      const embedded = EMBEDDED_PRICE_HISTORY[ticker] || [];
      series = embedded
        .map(p => ({ date: p[0], close: +p[1] }))
        .filter(p => p.date && Number.isFinite(p.close));
    }

    // Keep tooltip light: only retain up to 140 points.
    series = downsampleEvenly(series, 140);

    priceCache.set(ticker, series);
    return series;
  }

  function renderLegend(sectors, color) {
    const legend = d3.select('#legend');
    legend.selectAll('*').remove();

    const items = legend
      .selectAll('div.legend-item')
      .data(sectors, d => d)
      .join('div')
      .attr('class', 'legend-item');

    items.append('span')
      .attr('class', 'legend-swatch')
      .style('background', d => color(d));

    items.append('span')
      .attr('class', 'legend-label')
      .text(d => d);
  }

  function renderSparkline(svgSel, series) {
    const w = 260;
    const h = 48;

    svgSel.selectAll('*').remove();

    const points = downsampleEvenly(series, 120);
    if (points.length < 2) return;

    const yExtent = d3.extent(points, d => d.close);
    const x = d3.scaleLinear().domain([0, points.length - 1]).range([0, w]);
    const y = d3.scaleLinear().domain(yExtent).nice().range([h - 2, 2]);

    const area = d3.area()
      .x((d, i) => x(i))
      .y0(h - 2)
      .y1(d => y(d.close))
      .curve(d3.curveMonotoneX);

    const line = d3.line()
      .x((d, i) => x(i))
      .y(d => y(d.close))
      .curve(d3.curveMonotoneX);

    svgSel.append('path')
      .datum(points)
      .attr('d', area)
      .attr('fill', 'rgba(154, 209, 255, 0.18)');

    svgSel.append('path')
      .datum(points)
      .attr('d', line)
      .attr('fill', 'none')
      .attr('stroke', 'rgba(154, 209, 255, 0.95)')
      .attr('stroke-width', 1.6);

    const last = points[points.length - 1];
    svgSel.append('circle')
      .attr('cx', x(points.length - 1))
      .attr('cy', y(last.close))
      .attr('r', 2.3)
      .attr('fill', 'rgba(255, 255, 255, 0.95)');
  }

  function moveTooltip(event) {
    const node = tooltip.node();
    if (!node) return;

    const rect = node.getBoundingClientRect();
    const pageX = event.pageX ?? 0;
    const pageY = event.pageY ?? 0;

    const maxX = window.scrollX + window.innerWidth - rect.width - 8;
    const maxY = window.scrollY + window.innerHeight - rect.height - 8;

    const x = Math.min(maxX, pageX + TOOLTIP_PAD);
    const y = Math.min(maxY, pageY + TOOLTIP_PAD);

    tooltip.style('left', `${Math.max(window.scrollX + 8, x)}px`);
    tooltip.style('top', `${Math.max(window.scrollY + 8, y)}px`);
  }

  function hideTooltip() {
    tooltip.classed('visible', false).attr('aria-hidden', 'true');
  }

  function showTooltip(event, d) {
    if (d.isETF) return;

    tooltip
      .attr('data-ticker', d.ticker)
      .attr('aria-hidden', 'false')
      .classed('visible', true)
      .html(`
        <div class="tt-title">${escapeHtml(d.ticker)}<\/div>
        <div class="tt-name">${escapeHtml(d.fullName)}<\/div>
        <div class="tt-grid">
          <div class="tt-label">Sector<\/div><div>${escapeHtml(d.sector)}<\/div>
          <div class="tt-label">Market cap<\/div><div>${escapeHtml(formatMarketCap(d.marketCap))}<\/div>
          <div class="tt-label">Country<\/div><div>${escapeHtml(d.country || '—')}<\/div>
          <div class="tt-label">Website<\/div><div>${d.website ? `<a href="${escapeHtml(d.website)}" target="_blank" rel="noopener noreferrer">${escapeHtml(d.website)}<\/a>` : '—'}<\/div>
        <\/div>
        <div class="spark-wrap">
          <div class="tt-label" style="margin-bottom: 4px;">Price history (sparkline)<\/div>
          <svg class="sparkline" viewBox="0 0 260 48" preserveAspectRatio="none"><\/svg>
        <\/div>
      `);

    moveTooltip(event);

    const current = d.ticker;
    loadPriceSeries(d.ticker)
      .then(series => {
        if (!series || !series.length) return;
        if (!tooltip.classed('visible')) return;
        if (tooltip.attr('data-ticker') !== current) return;
        renderSparkline(tooltip.select('svg.sparkline'), series);
      })
      .catch(() => { /* ignore */ });
  }

  function computeSectorCenters(sectors, width, height) {
    const padX = Math.max(24, width * 0.14);
    const padY = Math.max(24, height * 0.14);

    const plotWidth = Math.max(1, width - padX * 2);
    const plotHeight = Math.max(1, height - padY * 2);

    const cols = Math.ceil(Math.sqrt(sectors.length));
    const rows = Math.ceil(sectors.length / cols);

    const xStep = plotWidth / cols;
    const yStep = plotHeight / rows;

    const centers = new Map();
    sectors.forEach((sector, i) => {
      const col = i % cols;
      const row = Math.floor(i / cols);
      centers.set(sector, {
        x: padX + xStep / 2 + col * xStep,
        y: padY + yStep / 2 + row * yStep,
      });
    });

    return centers;
  }

  function renderApp(stocks) {
    const cleaned = stocks
      .filter(d => d.ticker)
      .map(d => ({ ...d, sector: d.sector || 'Unknown' }));

    const sectors = Array.from(new Set(cleaned.map(d => d.sector)))
      .sort(d3.ascending);

    const palette = sectors.length <= d3.schemeSet3.length
      ? d3.schemeSet3.slice(0, sectors.length)
      : d3.quantize(d3.interpolateRainbow, sectors.length);

    const color = d3.scaleOrdinal().domain(sectors).range(palette);
    renderLegend(sectors, color);

    // --- Table
    const tableData = cleaned
      .slice()
      .sort((a, b) => {
        const am = a.marketCap == null ? -Infinity : a.marketCap;
        const bm = b.marketCap == null ? -Infinity : b.marketCap;
        const byCap = d3.descending(am, bm);
        return byCap || d3.ascending(a.ticker, b.ticker);
      });

    const tbody = d3.select('#stockTable tbody');
    tbody.selectAll('*').remove();

    let rowSel = tbody
      .selectAll('tr')
      .data(tableData, d => d.ticker)
      .join('tr')
      .attr('data-ticker', d => d.ticker);

    rowSel.append('td').text(d => d.ticker);
    rowSel.append('td').text(d => d.fullName);
    rowSel.append('td').text(d => d.sector);
    rowSel.append('td').text(d => formatMarketCap(d.marketCap));

    // --- Bubble chart
    const svg = d3.select('#bubbleChart');
    const box = svg.node().getBoundingClientRect();
    const width = Math.max(MIN_CHART_WIDTH, Math.floor(box.width || MIN_CHART_WIDTH));
    const height = CHART_HEIGHT;

    svg
      .attr('viewBox', `0 0 ${width} ${height}`)
      .attr('preserveAspectRatio', 'xMidYMid meet');

    svg.selectAll('*').remove();

    const marketCaps = cleaned.filter(d => d.marketCap != null).map(d => d.marketCap);
    const capExtent = d3.extent(marketCaps);

    const rScale = d3.scaleSqrt()
      .domain(capExtent)
      .range([10, 52])
      .clamp(true);

    const etfRadius = 14;
    cleaned.forEach(d => {
      d.radius = d.marketCap != null ? rScale(d.marketCap) : etfRadius;
    });

    const centers = computeSectorCenters(sectors, width, height);

    // Deterministic initial positions: stable order within each sector.
    const bySector = d3.group(cleaned, d => d.sector);
    for (const [sector, arr] of bySector) {
      const c = centers.get(sector) || { x: width / 2, y: height / 2 };
      arr
        .slice()
        .sort((a, b) => d3.ascending(a.ticker, b.ticker))
        .forEach((d, i) => {
          const angle = (i * 2 * Math.PI) / Math.max(1, arr.length);
          const spiral = 4 * Math.sqrt(i);
          d.x = c.x + spiral * Math.cos(angle);
          d.y = c.y + spiral * Math.sin(angle);
          d.vx = 0;
          d.vy = 0;
        });
    }

    const simulation = d3.forceSimulation(cleaned)
      .randomSource(d3.randomLcg(0.42))
      .force('x', d3.forceX(d => (centers.get(d.sector) || { x: width / 2 }).x).strength(0.18))
      .force('y', d3.forceY(d => (centers.get(d.sector) || { y: height / 2 }).y).strength(0.18))
      .force('collide', d3.forceCollide(d => d.radius + 1.6).iterations(3))
      .force('charge', d3.forceManyBody().strength(-8))
      .stop();

    for (let i = 0; i < FORCE_TICKS; i += 1) simulation.tick();

    cleaned.forEach(d => {
      d.x = Math.max(d.radius, Math.min(width - d.radius, d.x));
      d.y = Math.max(d.radius, Math.min(height - d.radius, d.y));
    });

    const nodeLayer = svg.append('g').attr('class', 'node-layer');

    let nodeSel = nodeLayer
      .selectAll('g.node')
      .data(cleaned.slice().sort((a, b) => d3.ascending(a.ticker, b.ticker)), d => d.ticker)
      .join('g')
      .attr('class', 'node')
      .attr('transform', d => `translate(${d.x},${d.y})`)
      .style('cursor', 'pointer');

    nodeSel.append('circle')
      .attr('r', d => d.radius)
      .attr('fill', d => color(d.sector))
      .attr('fill-opacity', 0.92);

    nodeSel.append('text')
      .text(d => d.ticker)
      .attr('text-anchor', 'middle')
      .attr('dy', '0.35em')
      .style('font-size', d => `${Math.max(9, Math.min(14, d.radius * 0.55))}px`)
      .style('pointer-events', 'none');

    function setSelected(ticker) {
      selectedTicker = ticker;
      nodeSel.classed('selected', d => selectedTicker != null && d.ticker === selectedTicker);
      rowSel.classed('selected', d => selectedTicker != null && d.ticker === selectedTicker);

      if (selectedTicker) {
        const row = document.querySelector(`tr[data-ticker="${CSS.escape(selectedTicker)}"]`);
        if (row) row.scrollIntoView({ block: 'nearest' });
      }
    }

    rowSel.on('click', (event, d) => {
      event.preventDefault();
      setSelected(d.ticker === selectedTicker ? null : d.ticker);
    });

    nodeSel
      .on('click', (event, d) => {
        event.stopPropagation();
        setSelected(d.ticker === selectedTicker ? null : d.ticker);
      })
      .on('mouseenter', (event, d) => showTooltip(event, d))
      .on('mousemove', (event, d) => { if (!d.isETF && tooltip.classed('visible')) moveTooltip(event); })
      .on('mouseleave', () => hideTooltip());

    svg.on('click', () => {
      setSelected(null);
      hideTooltip();
    });
  }

  loadStocks()
    .then(renderApp)
    .catch(err => {
      console.error(err);
      d3.select('#bubble-panel')
        .append('div')
        .style('color', 'crimson')
        .style('margin-top', '8px')
        .text('Failed to load data. Please open the page via a local web server.');
    });
})();
